  terms: [["SMAW (stick)", "Shielded metal arc welding: uses a flux-coated electrode; good for outdoor and repair work."], ["GMAW (MIG)", "Gas metal arc welding: uses a continuously fed wire and shielding gas."], ["FCAW (flux-core)", "Flux-cored arc welding: a wire-fed process with flux in the wire."], ["GTAW (TIG)", "Gas tungsten arc welding: precise welding with a tungsten electrode and separate filler."], ["Bead", "The deposit of weld metal along a joint."], ["Weld puddle", "The molten metal pool the welder controls."], ["Fillet weld", "A triangular weld joining two surfaces at roughly right angles."], ["Groove weld", "A weld made in a prepared groove between parts, often for full penetration."], ["Porosity", "Gas pockets trapped in a weld, usually from contamination or poor shielding."], ["Undercut", "A groove melted into the base metal next to the weld that isn’t filled."], ["Slag", "A crust left on stick and flux-core welds that must be removed."], ["Polarity (DCEP)", "Direct current electrode positive: the most common polarity for stick and MIG."], ["Weld positions (1G–6G)", "Codes describing joint orientation, from flat (1G) to fixed pipe at 45 degrees (6G)."], ["Preheat", "Heating metal before welding to reduce cracking."], ["Hot work permit", "Authorization required before welding in areas with fire risk."]],
  howto: [
    { t: "Set Up a MIG Welder", intro: "Proper setup prevents most MIG problems. Always check the machine’s manual.", steps: ["Inspect cables, the gun, the ground clamp and the gas hose for damage.", "Install the correct wire type and diameter and set drive roll tension.", "Match the contact tip size to the wire and install the nozzle.", "Connect shielding gas (commonly 75% argon/25% CO2 for mild steel) and set flow to roughly 20–30 cubic feet per hour.", "Set polarity to DCEP for solid wire.", "Use the machine’s chart to set voltage and wire feed speed for the metal thickness.", "Clamp the ground to clean bare metal and run a test bead on scrap, adjusting as needed."], tip: "A good MIG weld sounds like bacon frying. Popping or spatter usually means voltage or wire speed needs adjusting." },
    { t: "Run a Horizontal Fillet Weld", intro: "The horizontal fillet (2F) is one of the most common welds in fabrication.", steps: ["Clean mill scale, rust and oil from both pieces and fit them tightly at 90 degrees.", "Tack weld the joint at each end.", "Hold the gun at about 45 degrees between the plates, with a slight 10–15 degree push or drag angle per the process.", "Strike the arc and establish a puddle at the root of the joint.", "Travel at a steady speed, keeping the wire aimed slightly toward the bottom plate.", "Watch that both toes of the weld wet into the base metal without undercut.", "Clean and inspect the weld for size, profile and defects."], tip: "Gravity pulls the puddle down in horizontal welds: aim slightly into the lower plate to keep legs equal." },
    { t: "Inspect a Weld for Common Defects", intro: "Visual inspection is the first line of quality control.", steps: ["Let the weld cool and clean off slag and spatter.", "Check the weld size and length against the drawing.", "Look for cracks. Any crack is generally rejectable.", "Check for porosity (pinholes) on the surface.", "Look for undercut along the toes of the weld.", "Check for overlap, incomplete fusion and uneven profile.", "Mark and repair defects according to the procedure, then reinspect."], tip: "Good light and a magnifier make small defects much easier to see." }
  ],
